This uses `getline()` (POSIX), which grows its buffer automatically, so long lines are never cut in half.

```c
#define _POSIX_C_SOURCE 200809L
#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[])
{
    if (argc != 2) {
        fprintf(stderr, "usage: %s FILE\n", argv[0]);
        return EXIT_FAILURE;
    }
    FILE *fp = fopen(argv[1], "r");
    if (fp == NULL) {
        perror(argv[1]);
        return EXIT_FAILURE;
    }
    char *line = NULL;   /* getline allocates this */
    size_t cap = 0;      /* current buffer size */
    ssize_t len;
    unsigned long n = 0;
    while ((len = getline(&line, &cap, fp)) != -1) {
        printf("%6lu  %s", ++n, line);
        if (line[len - 1] != '\n')   /* last line had no newline */
            putchar('\n');
    }
    int rc = EXIT_SUCCESS;
    if (ferror(fp)) {
        perror("read");
        rc = EXIT_FAILURE;
    }
    free(line);
    fclose(fp);
    return rc;
}
```

Build and run:
1. `cc -std=c11 -Wall -Wextra -o numlines numlines.c`
2. `./numlines /etc/hosts`

Key points:
- `getline()` returns -1 at end of file *or* on error. `ferror()` tells you which one.
- You must `free()` the buffer once, after the loop, not inside it.
- `perror(argv[1])` prints the file name plus the reason, e.g. `notes.txt: No such file or directory`.

When the file does not exist my program prints `open failed: Inappropriate ioctl for device` instead of "No such file or directory". It only happens when I redirect output to a file. Code:

```c
FILE *f = fopen(path, "r");
if (!f) {
    printf("could not open %s\n", path);
    perror("open failed");
}
```

`errno` is a global error code. Any library call may change it. Your `printf()` runs between `fopen()` and `perror()`. When stdout is redirected, stdio checks whether stdout is a terminal (an `ioctl` call), that check fails, and it overwrites `errno` with `ENOTTY`.

Fix: read `errno` immediately after the failing call.

```c
FILE *f = fopen(path, "r");
if (!f) {
    int err = errno;            /* save it first */
    fprintf(stderr, "could not open %s: %s\n", path, strerror(err));
}
```

Key points:
- Include `<errno.h>` and `<string.h>`.
- Only trust `errno` right after a call that *reported* failure.

Two details matter: `write()` may write fewer bytes than asked (a *partial write*), and both calls can fail with `EINTR` (interrupted by a signal). The helper `write_all()` handles both.

```c
#define _POSIX_C_SOURCE 200809L
#include <errno.h>
#include <fcntl.h>
#include <stdio.h>
#include <unistd.h>

static int write_all(int fd, const char *buf, size_t n)
{
    while (n > 0) {
        ssize_t w = write(fd, buf, n);
        if (w < 0) {
            if (errno == EINTR) continue;
            return -1;
        }
        buf += w;
        n -= (size_t)w;
    }
    return 0;
}

int main(int argc, char *argv[])
{
    if (argc != 3) {
        fprintf(stderr, "usage: %s SRC DST\n", argv[0]);
        return 1;
    }
    int in = open(argv[1], O_RDONLY);
    if (in < 0) { perror(argv[1]); return 1; }
    int out = open(argv[2], O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (out < 0) { perror(argv[2]); close(in); return 1; }

    char buf[65536];
    ssize_t r;
    int rc = 0;
    while ((r = read(in, buf, sizeof buf)) != 0) {
        if (r < 0) {
            if (errno == EINTR) continue;
            perror("read"); rc = 1; break;
        }
        if (write_all(out, buf, (size_t)r) < 0) {
            perror("write"); rc = 1; break;
        }
    }
    close(in);
    if (close(out) < 0) { perror("close"); rc = 1; }
    return rc;
}
```

Test: `./mycp /etc/hosts /tmp/h && cmp /etc/hosts /tmp/h && echo same`

Key points:
- `read()` returning 0 means end of file; negative means error.
- `0644` is the permission for a *new* file: owner read/write, others read.
- Check `close()` on the output file: some filesystems report write errors only there.

Why does my program print the last line of the file twice?

```c
char line[256];
while (!feof(fp)) {
    fgets(line, sizeof line, fp);
    printf("%s", line);
}
```

`feof()` does not predict the future. It only becomes true *after* a read has already tried to go past the end of the file.

What happens step by step:
1. `fgets()` reads the last line. The end-of-file flag is still false.
2. The loop runs again. `fgets()` finds nothing, returns `NULL`, and sets the EOF flag. `line` is left unchanged.
3. Your code ignores the `NULL` and prints the old `line` again.
4. Now `feof()` is true and the loop stops.

Fix: let the read call control the loop.

```c
char line[256];
while (fgets(line, sizeof line, fp) != NULL) {
    printf("%s", line);
}
if (ferror(fp)) {
    perror("fgets");
}
```

Key points:
- Always test the return value of the read function (`fgets`, `fread`, `getline`, `fscanf`), not `feof()`.
- Use `feof()`/`ferror()` *after* the loop to find out why it stopped.

Explain this output. I expected "start" once.

```c
#include <stdio.h>
#include <unistd.h>
int main(void) {
    printf("start ");
    fork();
    printf("end\n");
    return 0;
}
```
Output:
```
start end
start end
```

The cause is the stdio buffer, not `fork()` running code twice.

1. `printf("start ")` does not write to the terminal yet. It puts the text into stdout's *buffer* (a block of memory inside your process). Stdout to a terminal is *line-buffered*: it flushes on `\n`. There is no `\n`, so "start " waits.
2. `fork()` copies the whole process, including that buffer. Now parent and child both hold "start ".
3. Each process appends "end\n" and flushes. Each prints "start end".

If you redirect to a file (`./a.out > out.txt`), stdout is *fully buffered*, so even text that ends in `\n` gets duplicated.

Fix: flush before forking.

```c
#include <stdio.h>
#include <unistd.h>

int main(void)
{
    printf("start ");
    fflush(stdout);              /* empty the buffer before the copy */
    pid_t pid = fork();
    if (pid < 0) {
        perror("fork");
        return 1;
    }
    printf("end\n");
    return 0;
}
```

Output now: `start end` then `end` (order between parent and child may vary).

Key points:
- Call `fflush(stdout)` (or `fflush(NULL)` for all streams) before every `fork()`.
- In a child that will not `exec`, leave with `_exit()` so it does not flush copied buffers a second time.

The standard pattern is *fork* (copy the process), *exec* (replace the child's program), *wait* (parent collects the result).

```c
#define _POSIX_C_SOURCE 200809L
#include <stdio.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <unistd.h>

int main(void)
{
    pid_t pid = fork();
    if (pid < 0) {
        perror("fork");
        return 1;
    }
    if (pid == 0) {                       /* child */
        char *args[] = { "ls", "-l", "/tmp", NULL };
        execvp(args[0], args);
        perror("execvp");                 /* reached only if exec failed */
        _exit(127);
    }
    int status;                           /* parent */
    if (waitpid(pid, &status, 0) < 0) {
        perror("waitpid");
        return 1;
    }
    if (WIFEXITED(status))
        printf("child exited with code %d\n", WEXITSTATUS(status));
    else if (WIFSIGNALED(status))
        printf("child killed by signal %d\n", WTERMSIG(status));
    return 0;
}
```

Steps the program follows:
1. `fork()` returns 0 in the child and the child's PID in the parent.
2. The child calls `execvp()`, which searches `PATH` for `ls`. On success it never returns.
3. The parent blocks in `waitpid()` until the child ends.
4. The `W...` macros decode `status`: normal exit or killed by a signal.

Key points:
- The `args` array must end with `NULL`.
- Use `_exit()` in the child after a failed exec, so it does not run the parent's `atexit` handlers or flush stdio buffers.
- 127 is the shell convention for "command not found".

Ctrl+C sends `SIGINT` (a *signal*: an asynchronous notification from the kernel). The handler only sets a flag; the main loop checks the flag and does the cleanup.

```c
#define _POSIX_C_SOURCE 200809L
#include <signal.h>
#include <stdio.h>
#include <string.h>
#include <unistd.h>

static volatile sig_atomic_t stop = 0;

static void on_sigint(int sig)
{
    (void)sig;
    stop = 1;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof sa);
    sa.sa_handler = on_sigint;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }
    unsigned long ticks = 0;
    while (!stop) {
        printf("tick %lu\n", ++ticks);
        fflush(stdout);
        sleep(1);            /* returns early if a signal arrives */
    }
    printf("\ncaught SIGINT after %lu ticks, cleaning up\n", ticks);
    return 0;
}
```

Key points:
- `volatile sig_atomic_t` is the only variable type the C standard guarantees is safe to write from a handler. `volatile` stops the compiler caching the value in a register.
- Prefer `sigaction()` over `signal()`; `signal()` behaviour differs between systems.
- Do the real work (printing, freeing, closing files) in `main`, not in the handler.

Use `write()` with a fixed string. It is a direct system call with no stdio buffer.

```c
#include <errno.h>
#include <signal.h>
#include <unistd.h>

static void on_sigterm(int sig)
{
    (void)sig;
    int saved = errno;                      /* write() may change errno */
    static const char msg[] = "got SIGTERM\n";
    ssize_t r = write(STDERR_FILENO, msg, sizeof msg - 1);
    (void)r;                                /* nothing useful to do on failure */
    errno = saved;
}
```

Steps:
1. Use a `static const` string; do not build it with `sprintf()` (not safe).
2. `sizeof msg - 1` excludes the terminating `'\0'`.
3. Save and restore `errno`, so the interrupted code does not see a changed value.

Key points:
- If you need numbers in the message, convert them by hand into a local `char` array, or just set a flag and print from `main`.

My pipe program hangs forever after printing "hello". Why?

```c
int fd[2];
pipe(fd);
if (fork() == 0) {
    char buf[64];
    ssize_t n;
    while ((n = read(fd[0], buf, sizeof buf)) > 0)
        write(1, buf, n);
    return 0;
}
write(fd[1], "hello\n", 6);
wait(NULL);
```

`read()` on a pipe returns 0 (end of file) only when **every** copy of the write end is closed. After `fork()` there are two copies of `fd[1]`: one in the parent and one in the child. Nobody closes either.

1. Child reads "hello" and loops back to `read()`.
2. The write end is still open, so `read()` blocks waiting for more data.
3. Parent is blocked in `wait()` for the child. Both wait forever: a *deadlock*.

Fixed program:

```c
#define _POSIX_C_SOURCE 200809L
#include <stdio.h>
#include <sys/wait.h>
#include <unistd.h>

int main(void)
{
    int fd[2];
    if (pipe(fd) < 0) { perror("pipe"); return 1; }
    pid_t pid = fork();
    if (pid < 0) { perror("fork"); return 1; }
    if (pid == 0) {
        close(fd[1]);                 /* child only reads */
        char buf[64];
        ssize_t n;
        while ((n = read(fd[0], buf, sizeof buf)) > 0)
            if (write(STDOUT_FILENO, buf, (size_t)n) < 0) _exit(1);
        close(fd[0]);
        _exit(0);
    }
    close(fd[0]);                     /* parent only writes */
    if (write(fd[1], "hello\n", 6) < 0) perror("write");
    close(fd[1]);                     /* child's read() now returns 0 */
    if (waitpid(pid, NULL, 0) < 0) { perror("waitpid"); return 1; }
    return 0;
}
```

Key points:
- Right after `fork()`, each process closes the pipe end it does not use.
- Close the write end when you finish writing; that is how the reader learns "no more data".

Create a pipe, fork two children, and use `dup2()` to connect them. `dup2(old, new)` makes file descriptor `new` refer to the same open file as `old`.

```c
#define _POSIX_C_SOURCE 200809L
#include <stdio.h>
#include <sys/wait.h>
#include <unistd.h>

int main(void)
{
    int fd[2];
    if (pipe(fd) < 0) { perror("pipe"); return 1; }

    pid_t a = fork();
    if (a < 0) { perror("fork"); return 1; }
    if (a == 0) {                          /* ls: stdout -> pipe */
        if (dup2(fd[1], STDOUT_FILENO) < 0) _exit(126);
        close(fd[0]); close(fd[1]);
        execlp("ls", "ls", (char *)NULL);
        perror("execlp ls");
        _exit(127);
    }
    pid_t b = fork();
    if (b < 0) { perror("fork"); return 1; }
    if (b == 0) {                          /* wc: stdin <- pipe */
        if (dup2(fd[0], STDIN_FILENO) < 0) _exit(126);
        close(fd[0]); close(fd[1]);
        execlp("wc", "wc", "-l", (char *)NULL);
        perror("execlp wc");
        _exit(127);
    }
    close(fd[0]); close(fd[1]);            /* parent uses neither end */
    int st;
    waitpid(a, &st, 0);
    waitpid(b, &st, 0);
    return WIFEXITED(st) ? WEXITSTATUS(st) : 1;
}
```

Order of operations:
1. `pipe()` before `fork()`, so both children inherit it.
2. Each child: `dup2()`, then close both original pipe fds, then exec.
3. Parent closes both ends, then waits for both children.

Key points:
- If the parent keeps `fd[1]` open, `wc` never sees end of file and hangs.
- `execlp` argument lists must end with `(char *)NULL`.

This is a *data race*: two threads access the same variable at the same time and at least one writes. `counter++` is three steps: load, add, store. Both threads can load the same old value, and one increment is lost. In C11 a data race is undefined behaviour.

Fix: protect the update with a *mutex* (a lock only one thread can hold at a time).

```c
#include <pthread.h>
#include <stdio.h>

#define LOOPS 1000000

static long counter = 0;
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

static void *worker(void *arg)
{
    (void)arg;
    for (int i = 0; i < LOOPS; i++) {
        pthread_mutex_lock(&lock);
        counter++;
        pthread_mutex_unlock(&lock);
    }
    return NULL;
}

int main(void)
{
    pthread_t t1, t2;
    if (pthread_create(&t1, NULL, worker, NULL) != 0 ||
        pthread_create(&t2, NULL, worker, NULL) != 0) {
        fprintf(stderr, "pthread_create failed\n");
        return 1;
    }
    pthread_join(t1, NULL);
    pthread_join(t2, NULL);
    printf("counter = %ld\n", counter);   /* always 2000000 */
    return 0;
}
```

Build: `cc -std=c11 -Wall -Wextra -pthread race.c -o race`

Key points:
- pthread functions return an error number directly; they do not set `errno`.
- Find races automatically with ThreadSanitizer: `cc -g -fsanitize=thread race.c`.
- For a plain counter, C11 `atomic_long` from `<stdatomic.h>` is faster than a mutex.

