A *socket* is a file descriptor for network communication. A server does: socket, bind (attach to a port), listen, accept (wait for a client), then read/write.

```c
#define _POSIX_C_SOURCE 200809L
#include <arpa/inet.h>
#include <netinet/in.h>
#include <stdio.h>
#include <string.h>
#include <sys/socket.h>
#include <unistd.h>

int main(void)
{
    int srv = socket(AF_INET, SOCK_STREAM, 0);
    if (srv < 0) { perror("socket"); return 1; }
    int on = 1;
    setsockopt(srv, SOL_SOCKET, SO_REUSEADDR, &on, sizeof on);

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof addr);
    addr.sin_family = AF_INET;
    addr.sin_port = htons(5000);               /* host to network order */
    addr.sin_addr.s_addr = htonl(INADDR_ANY);  /* all interfaces */
    if (bind(srv, (struct sockaddr *)&addr, sizeof addr) < 0) {
        perror("bind"); close(srv); return 1;
    }
    if (listen(srv, 16) < 0) { perror("listen"); close(srv); return 1; }

    for (;;) {
        int cli = accept(srv, NULL, NULL);
        if (cli < 0) { perror("accept"); continue; }
        char buf[4096];
        ssize_t n;
        while ((n = recv(cli, buf, sizeof buf, 0)) > 0) {
            if (send(cli, buf, (size_t)n, 0) < 0) { perror("send"); break; }
        }
        close(cli);                            /* n == 0: client closed */
    }
}
```

Test:
1. Terminal 1: `./echo`
2. Terminal 2: `nc 127.0.0.1 5000`, type a line, it comes back.

Key points:
- `SO_REUSEADDR` lets you restart the server right away instead of getting "Address already in use".
- A real server must loop on `send()` for partial sends and handle many clients (fork, threads or `poll()`).

`getaddrinfo()` turns a host name and port into socket addresses. It supports IPv4 and IPv6, so try each result until one connects.

```c
#define _POSIX_C_SOURCE 200809L
#include <netdb.h>
#include <stdio.h>
#include <string.h>
#include <sys/socket.h>
#include <unistd.h>

int main(int argc, char *argv[])
{
    if (argc != 3) { fprintf(stderr, "usage: %s HOST PORT\n", argv[0]); return 1; }

    struct addrinfo hints, *res, *p;
    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC;        /* IPv4 or IPv6 */
    hints.ai_socktype = SOCK_STREAM;    /* TCP */
    int rc = getaddrinfo(argv[1], argv[2], &hints, &res);
    if (rc != 0) { fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(rc)); return 1; }

    int fd = -1;
    for (p = res; p != NULL; p = p->ai_next) {
        fd = socket(p->ai_family, p->ai_socktype, p->ai_protocol);
        if (fd < 0) continue;
        if (connect(fd, p->ai_addr, p->ai_addrlen) == 0) break;
        close(fd);
        fd = -1;
    }
    freeaddrinfo(res);
    if (fd < 0) { fprintf(stderr, "could not connect\n"); return 1; }

    char req[512];
    int len = snprintf(req, sizeof req, "GET / HTTP/1.0\r\nHost: %s\r\n\r\n", argv[1]);
    if (len < 0 || (size_t)len >= sizeof req) { close(fd); return 1; }
    if (send(fd, req, (size_t)len, 0) != len) { perror("send"); close(fd); return 1; }

    char buf[4096];
    ssize_t n;
    while ((n = recv(fd, buf, sizeof buf, 0)) > 0)
        fwrite(buf, 1, (size_t)n, stdout);
    if (n < 0) perror("recv");
    close(fd);
    return 0;
}
```

Run: `./client example.com 80`

Key points:
- `getaddrinfo` reports errors through its return value and `gai_strerror()`, not `errno`.
- Always call `freeaddrinfo()` on the list.
- HTTP/1.0 makes the server close the connection after replying, so `recv()` returns 0 at the end.

The old connections are in the TCP *TIME_WAIT* state: the kernel keeps the port reserved for up to a few minutes to catch late packets. Set `SO_REUSEADDR` **before** `bind()`:

```c
int on = 1;
if (setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &on, sizeof on) < 0)
    perror("setsockopt");
```

Key points:
- If it still fails, another process really holds the port. Check with `ss -ltnp` (Linux) or `lsof -iTCP:5000 -sTCP:LISTEN`.

TCP is a *byte stream*, not a message system. One `send()` on one side does not equal one `recv()` on the other. `recv()` may return 1, 2 or 3 bytes even if you asked for 4. If you ignore the return value, `len` is half-filled.

There is a second bug if you skip byte order: the sender must use `htonl()` and you must use `ntohl()` (network order = big-endian).

Fix: loop until you have exactly the number of bytes you need.

```c
#include <errno.h>
#include <stdint.h>
#include <arpa/inet.h>
#include <sys/socket.h>

/* Returns 0 on success, -1 on error or if the peer closed early. */
static int recv_all(int fd, void *buf, size_t n)
{
    char *p = buf;
    while (n > 0) {
        ssize_t r = recv(fd, p, n, 0);
        if (r < 0 && errno == EINTR) continue;
        if (r <= 0) return -1;     /* error, or 0 = connection closed */
        p += r;
        n -= (size_t)r;
    }
    return 0;
}

static int read_message(int fd, char *out, size_t cap, uint32_t *outlen)
{
    uint32_t netlen;
    if (recv_all(fd, &netlen, sizeof netlen) < 0) return -1;
    uint32_t len = ntohl(netlen);
    if (len > cap) return -1;      /* never trust a length from the network */
    if (recv_all(fd, out, len) < 0) return -1;
    *outlen = len;
    return 0;
}
```

Key points:
- Always use the return value of `recv()`; it is the only truth about how much arrived.
- Check the length against your buffer size before reading the payload. Skipping this is a classic remote buffer overflow.
- On Linux, `recv(fd, buf, n, MSG_WAITALL)` also waits for all `n` bytes, but it can still return less on a signal or close, so check anyway.

*UBSan* (UndefinedBehaviorSanitizer) adds runtime checks for undefined behaviour such as signed overflow, bad shifts and misaligned pointers.

```c
#include <limits.h>
#include <stdio.h>

static int sum(const int *a, int n)
{
    int total = 0;
    for (int i = 0; i < n; i++)
        total += a[i];          /* overflows for these inputs */
    return total;
}

int main(void)
{
    int a[] = { INT_MAX, 1 };
    printf("sum = %d\n", sum(a, 2));
    return 0;
}
```

Steps:
1. Build: `cc -std=c11 -g -fsanitize=undefined ovf.c -o ovf`
2. Run: `./ovf`
3. Output:
   ```
   ovf.c:8:15: runtime error: signed integer overflow: 2147483647 + 1 cannot be represented in type 'int'
   sum = -2147483648
   ```
4. The report gives file, line and column, and the exact values.
5. To make the program stop at the first error (useful in tests), add `-fno-sanitize-recover=all`.

Fix options:
- Use a wider type: `long long total`.
- Or check before adding: `if (a[i] > 0 && total > INT_MAX - a[i]) { /* overflow */ }`.

Key points:
- Signed overflow is undefined behaviour; unsigned overflow is defined (it wraps), so UBSan does not report unsigned by default.
- Combine sanitizers: `-fsanitize=address,undefined`.

Because `x + 1` overflowing is UB, the compiler is allowed to assume it never overflows. For non-overflowing math, `x + 1 < x` is always false, so the compiler deletes the whole `if`.

Correct check: test *before* doing the operation.

```c
#include <limits.h>
#include <stdio.h>

int main(void)
{
    int x = INT_MAX;
    if (x > INT_MAX - 1)
        puts("overflow");
    else
        printf("%d\n", x + 1);
    return 0;
}
```

GCC and Clang also have `__builtin_add_overflow(a, b, &result)`, which returns true if the result did not fit. It is not standard C, but it is clear and fast. (C23 adds `ckd_add()` in `<stdckdint.h>`.)

Key points:
- Never detect overflow by looking at the result. Check the operands first.

`malloc(n * size)` is dangerous: if `n * size` is larger than `SIZE_MAX`, the multiplication wraps around to a small number. `malloc` succeeds with a tiny block, and later writes overflow the heap. This is a common security bug.

Check before multiplying:

```c
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>

/* Returns NULL if n * size would overflow or malloc fails. */
static void *alloc_array(size_t n, size_t size)
{
    if (size != 0 && n > SIZE_MAX / size)
        return NULL;
    return malloc(n * size);
}

int main(void)
{
    int *ok = alloc_array(1000, sizeof *ok);
    printf("1000 ints: %s\n", ok ? "allocated" : "refused");

    void *bad = alloc_array(SIZE_MAX / 2, 4);
    printf("huge request: %s\n", bad ? "allocated" : "refused");

    free(ok);
    free(bad);
    return 0;
}
```

Output:
```
1000 ints: allocated
huge request: refused
```

Why the check works: `n * size <= SIZE_MAX` is equivalent to `n <= SIZE_MAX / size` for integer division, and the division itself cannot overflow.

Alternatives:
1. `calloc(n, size)` performs the same check and also zeroes the memory.
2. `reallocarray(ptr, n, size)` checks overflow for resizing. It exists on OpenBSD, FreeBSD and glibc 2.26+, and is in POSIX 2024; older systems may lack it.

Key points:
- `size_t` is unsigned, so wrap-around is defined (no crash, no UBSan report) and silent. That is what makes it dangerous.
- `free(NULL)` is allowed and does nothing.

