Bit *n* is the value `1u << n`. Combine it with bitwise operators:
- OR `|` sets a bit, AND with NOT `& ~` clears it, XOR `^` flips it, AND `&` tests it.

```c
#include <stdint.h>
#include <stdio.h>

#define BIT(n)            (UINT32_C(1) << (n))
#define SET_BIT(x, n)     ((x) |=  BIT(n))
#define CLEAR_BIT(x, n)   ((x) &= ~BIT(n))
#define TOGGLE_BIT(x, n)  ((x) ^=  BIT(n))
#define TEST_BIT(x, n)    (((x) & BIT(n)) != 0)

static void print_bin(const char *label, uint8_t v)
{
    printf("%-8s ", label);
    for (int i = 7; i >= 0; i--)
        putchar(TEST_BIT(v, i) ? '1' : '0');
    putchar('\n');
}

int main(void)
{
    uint8_t flags = 0;
    print_bin("start", flags);
    SET_BIT(flags, 0);    print_bin("set 0", flags);
    SET_BIT(flags, 3);    print_bin("set 3", flags);
    TOGGLE_BIT(flags, 7); print_bin("flip 7", flags);
    CLEAR_BIT(flags, 0);  print_bin("clear 0", flags);
    printf("bit 3 is %d\n", TEST_BIT(flags, 3));
    return 0;
}
```

Output:
```
start    00000000
set 0    00000001
set 3    00001001
flip 7   10001001
clear 0  10001000
bit 3 is 1
```

Key points:
- Use unsigned types for bit work. `1 << 31` on a 32-bit signed `int` is undefined behaviour; `UINT32_C(1) << 31` is fine.
- Bit numbers start at 0 for the lowest (rightmost) bit.
- The macros evaluate `n` once, but use them only with simple arguments (no `i++`).

Kernighan's trick: `x & (x - 1)` clears the lowest set bit, so the loop runs once per 1 bit.

```c
unsigned popcount(unsigned x)
{
    unsigned count = 0;
    while (x) {
        x &= x - 1;
        count++;
    }
    return count;
}
```

Key points:
- GCC/Clang `__builtin_popcount(x)` compiles to one CPU instruction when you build with `-mpopcnt` or `-march=native` (x86). C23 adds `stdc_count_ones()` in `<stdbit.h>`.

*Endianness* is the order in which a multi-byte number is stored in memory.
- *Little-endian* (x86, most ARM setups): lowest byte first. `0x11223344` is stored as `44 33 22 11`.
- *Big-endian*: highest byte first: `11 22 33 44`. Network protocols use big-endian, called *network byte order*.

`htonl()` means "host to network, long (32-bit)". On a little-endian machine it reverses the bytes; on a big-endian machine it does nothing.

A program that shows both:

```c
#include <arpa/inet.h>
#include <stdint.h>
#include <stdio.h>

static void dump(const char *label, uint32_t v)
{
    const unsigned char *p = (const unsigned char *)&v;
    printf("%-6s", label);
    for (size_t i = 0; i < sizeof v; i++)
        printf(" %02x", p[i]);
    putchar('\n');
}

int main(void)
{
    uint32_t x = 0x11223344;
    dump("host", x);
    dump("htonl", htonl(x));
    printf("this machine is %s-endian\n",
           *(const unsigned char *)&x == 0x44 ? "little" : "big");
    return 0;
}
```

Output on x86-64 or Apple Silicon:
```
host   44 33 22 11
htonl  11 22 33 44
this machine is little-endian
```

Key points:
- Reading any object through `unsigned char *` is allowed by C; it is the standard way to inspect bytes.
- Convert with `htons/htonl` before sending, `ntohs/ntohl` after receiving.
- The *value* `x` is the same on every machine; only its memory layout differs.

Build the value with shifts. Shifts work on *values*, not memory layout, so the code gives the same result on every CPU and never does an unaligned read.

```c
#include <stdint.h>
#include <stdio.h>

static uint32_t load_be32(const unsigned char *p)
{
    return (uint32_t)p[0] << 24 |
           (uint32_t)p[1] << 16 |
           (uint32_t)p[2] << 8  |
           (uint32_t)p[3];
}

static void store_be32(unsigned char *p, uint32_t v)
{
    p[0] = (unsigned char)(v >> 24);
    p[1] = (unsigned char)(v >> 16);
    p[2] = (unsigned char)(v >> 8);
    p[3] = (unsigned char)v;
}

int main(void)
{
    /* PNG files start with an 8-byte signature, then a big-endian chunk length. */
    const unsigned char hdr[] = { 0x89, 'P', 'N', 'G', 0x0d, 0x0a, 0x1a, 0x0a,
                                  0x00, 0x00, 0x00, 0x0d };
    printf("chunk length = %u\n", (unsigned)load_be32(hdr + 8));   /* 13 */

    unsigned char out[4];
    store_be32(out, 0xCAFEBABE);
    printf("%02x %02x %02x %02x\n", out[0], out[1], out[2], out[3]);
    return 0;
}
```

Output:
```
chunk length = 13
ca fe ba be
```

Key points:
- Cast each byte to `uint32_t` before shifting. `p[0] << 24` alone promotes to `int`, and a byte >= 0x80 shifted that far overflows `int`, which is undefined behaviour.
- Avoid `*(uint32_t *)buf`: it can be misaligned and breaks strict aliasing rules.

C stores 2D arrays in *row-major* order: `a[0][0], a[0][1], ...` sit next to each other in memory. The CPU loads memory in *cache lines* (usually 64 bytes = 16 ints). Walking along a row uses all 16 ints from each line. Walking down a column jumps `N * 4` bytes each step, so almost every access is a cache miss.

```c
#define _POSIX_C_SOURCE 200809L
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define N 4096

static double now(void)
{
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (double)ts.tv_sec + (double)ts.tv_nsec / 1e9;
}

int main(void)
{
    int (*a)[N] = malloc(sizeof(int[N][N]));   /* 64 MiB on the heap */
    if (a == NULL) { perror("malloc"); return 1; }
    for (size_t i = 0; i < N; i++)
        for (size_t j = 0; j < N; j++)
            a[i][j] = (int)(i + j) & 7;

    long long sum = 0;
    double t0 = now();
    for (size_t i = 0; i < N; i++)          /* rows: sequential */
        for (size_t j = 0; j < N; j++)
            sum += a[i][j];
    double t1 = now();
    for (size_t j = 0; j < N; j++)          /* columns: stride N */
        for (size_t i = 0; i < N; i++)
            sum += a[i][j];
    double t2 = now();

    printf("rows:    %.3f s\ncolumns: %.3f s\n(sum %lld)\n", t1 - t0, t2 - t1, sum);
    free(a);
    return 0;
}
```

Build with optimisation: `cc -std=c11 -O2 cache.c -o cache`. Columns are typically several times slower; the exact ratio depends on the CPU.

Key points:
- Make the innermost loop walk the last index (`j` in `a[i][j]`).
- Printing `sum` stops the compiler from deleting the loops as unused work.
- Too big for the stack, so the array is allocated with `malloc`.

My bank transfer program freezes sometimes. Thread 1 calls transfer(&a, &b) and thread 2 calls transfer(&b, &a).

```c
void transfer(struct account *from, struct account *to, int amt) {
    pthread_mutex_lock(&from->lock);
    pthread_mutex_lock(&to->lock);
    from->balance -= amt;
    to->balance += amt;
    pthread_mutex_unlock(&to->lock);
    pthread_mutex_unlock(&from->lock);
}
```

This is a *deadlock*: each thread holds one lock and waits forever for the other.

1. Thread 1 locks `a`, then wants `b`.
2. Thread 2 locks `b`, then wants `a`.
3. Neither can continue.

Fix: always take the locks in the same global order. Here the order is by account id.

```c
#include <pthread.h>
#include <stdio.h>

struct account { int id; long balance; pthread_mutex_t lock; };

static void transfer(struct account *from, struct account *to, long amt)
{
    struct account *first  = from->id < to->id ? from : to;
    struct account *second = from->id < to->id ? to : from;
    pthread_mutex_lock(&first->lock);
    pthread_mutex_lock(&second->lock);
    from->balance -= amt;
    to->balance += amt;
    pthread_mutex_unlock(&second->lock);
    pthread_mutex_unlock(&first->lock);
}

static struct account a = { 1, 1000, PTHREAD_MUTEX_INITIALIZER };
static struct account b = { 2, 1000, PTHREAD_MUTEX_INITIALIZER };

static void *t1(void *arg) { (void)arg; for (int i = 0; i < 100000; i++) transfer(&a, &b, 1); return NULL; }
static void *t2(void *arg) { (void)arg; for (int i = 0; i < 100000; i++) transfer(&b, &a, 1); return NULL; }

int main(void)
{
    pthread_t x, y;
    if (pthread_create(&x, NULL, t1, NULL) != 0) return 1;
    if (pthread_create(&y, NULL, t2, NULL) != 0) return 1;
    pthread_join(x, NULL);
    pthread_join(y, NULL);
    printf("a=%ld b=%ld total=%ld\n", a.balance, b.balance, a.balance + b.balance);
    return 0;
}
```

Output: `a=1000 b=1000 total=2000`

Key points:
- To see a live deadlock, attach gdb (`gdb -p PID`) and run `thread apply all bt`; both threads sit in `pthread_mutex_lock`.
- This code assumes `from != to`. Locking the same mutex twice also deadlocks, so reject that case first.

A *condition variable* lets a thread sleep until another thread signals that something changed. It is always used with a mutex and a `while` loop that rechecks the condition.

```c
#include <pthread.h>
#include <stdio.h>

#define CAP 4
#define ITEMS 10

static int buf[CAP];
static int head, tail, count;
static pthread_mutex_t mu = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t not_full = PTHREAD_COND_INITIALIZER;
static pthread_cond_t not_empty = PTHREAD_COND_INITIALIZER;

static void *producer(void *arg)
{
    (void)arg;
    for (int i = 1; i <= ITEMS; i++) {
        pthread_mutex_lock(&mu);
        while (count == CAP)
            pthread_cond_wait(&not_full, &mu);   /* unlocks mu while sleeping */
        buf[tail] = i;
        tail = (tail + 1) % CAP;
        count++;
        pthread_cond_signal(&not_empty);
        pthread_mutex_unlock(&mu);
    }
    return NULL;
}

static void *consumer(void *arg)
{
    (void)arg;
    for (int i = 0; i < ITEMS; i++) {
        pthread_mutex_lock(&mu);
        while (count == 0)
            pthread_cond_wait(&not_empty, &mu);
        int v = buf[head];
        head = (head + 1) % CAP;
        count--;
        pthread_cond_signal(&not_full);
        pthread_mutex_unlock(&mu);
        printf("consumed %d\n", v);
    }
    return NULL;
}

int main(void)
{
    pthread_t p, c;
    if (pthread_create(&p, NULL, producer, NULL) != 0) return 1;
    if (pthread_create(&c, NULL, consumer, NULL) != 0) return 1;
    pthread_join(p, NULL);
    pthread_join(c, NULL);
    return 0;
}
```

Key points:
- Use `while`, not `if`, around `pthread_cond_wait`: threads can wake up without a signal (*spurious wakeup*), or another thread may take the item first.
- `pthread_cond_wait` atomically releases the mutex and sleeps, then re-locks before returning.
- Do slow work (here `printf`) after unlocking.

All my threads print the same id, or random ids. Why?

```c
for (int i = 0; i < 4; i++)
    pthread_create(&t[i], NULL, worker, &i);
```
worker does `int id = *(int *)arg; printf("thread %d\n", id);`

Every thread receives the address of the **same** variable `i`. By the time a thread reads it, the loop has usually changed it (often to 4). That is also a data race. After the loop ends, `i` no longer exists, so the pointer may even be dangling.

Fix: give each thread its own storage that lives until the thread is done.

```c
#include <pthread.h>
#include <stdio.h>

#define N 4

static void *worker(void *arg)
{
    int id = *(const int *)arg;
    printf("thread %d\n", id);
    return NULL;
}

int main(void)
{
    pthread_t t[N];
    int ids[N];                         /* one slot per thread */
    for (int i = 0; i < N; i++) {
        ids[i] = i;
        int rc = pthread_create(&t[i], NULL, worker, &ids[i]);
        if (rc != 0) {
            fprintf(stderr, "pthread_create failed: %d\n", rc);
            return 1;
        }
    }
    for (int i = 0; i < N; i++)
        pthread_join(t[i], NULL);       /* ids[] outlives all threads */
    return 0;
}
```

Output: `thread 0` to `thread 3`, in any order.

Key points:
- The data behind the argument pointer must stay valid until the thread has read it. A local array in `main` works because `main` joins every thread before returning.
- For per-thread structs with more fields, `malloc` one per thread and let the thread `free` it.

Those are zombies: finished children whose exit status nobody collected. Reap them with a `SIGCHLD` handler. The kernel sends `SIGCHLD` to the parent whenever a child exits.

```c
#define _POSIX_C_SOURCE 200809L
#include <errno.h>
#include <signal.h>
#include <string.h>
#include <sys/wait.h>

static void on_sigchld(int sig)
{
    (void)sig;
    int saved = errno;
    while (waitpid(-1, NULL, WNOHANG) > 0)
        ;                                  /* reap every finished child */
    errno = saved;
}

static int install_reaper(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof sa);
    sa.sa_handler = on_sigchld;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART | SA_NOCLDSTOP;
    return sigaction(SIGCHLD, &sa, NULL);
}
```

Call `install_reaper()` once at startup, before the `accept()` loop.

Key points:
- `waitpid(-1, ..., WNOHANG)` means "any child, do not block".
- `SA_RESTART` makes `accept()` resume instead of failing with `EINTR` when the signal arrives.

Use `fwrite()` and `fread()` with the `"wb"`/`"rb"` modes. Check the item count each call returns.

```c
#include <stdio.h>

struct rec { int id; double score; };

int main(void)
{
    struct rec out[3] = { {1, 9.5}, {2, 7.25}, {3, 8.0} };
    FILE *f = fopen("recs.bin", "wb");
    if (!f) { perror("fopen"); return 1; }
    size_t w = fwrite(out, sizeof out[0], 3, f);
    if (fclose(f) != 0 || w != 3) { fprintf(stderr, "write failed\n"); return 1; }

    struct rec in[3];
    f = fopen("recs.bin", "rb");
    if (!f) { perror("fopen"); return 1; }
    size_t r = fread(in, sizeof in[0], 3, f);
    fclose(f);
    if (r != 3) { fprintf(stderr, "read %zu of 3 records\n", r); return 1; }

    for (size_t i = 0; i < r; i++)
        printf("id=%d score=%.2f\n", in[i].id, in[i].score);
    return 0;
}
```

Output:
```
id=1 score=9.50
id=2 score=7.25
id=3 score=8.00
```

Limits of this format (raw memory dump):
1. *Padding*: the compiler inserts unused bytes between fields for alignment. Here `sizeof(struct rec)` is usually 16, not 12.
2. *Endianness*: a file written on a little-endian machine reads wrong on big-endian.
3. Compiler and type sizes can differ between platforms.

So this is fine for a cache read by the same program on the same machine. For files that move between systems, write each field explicitly in a fixed byte order (see `store_be32`-style helpers), or use a text format.

Key points:
- `fwrite`/`fread` return the number of *items*, not bytes.
- Never write structs that contain pointers; the address is meaningless when read back.

141 = 128 + 13. The shell adds 128 to the signal number, and signal 13 is `SIGPIPE`.

What happens:
1. The client closes its socket.
2. Your server calls `send()`/`write()` on that socket.
3. The kernel sends `SIGPIPE` to your process. Its default action is to terminate silently.

Fix: ignore the signal and handle the error code instead.

```c
#define _POSIX_C_SOURCE 200809L
#include <errno.h>
#include <signal.h>
#include <stdio.h>
#include <sys/socket.h>

int main(void)
{
    /* Once at startup: */
    if (signal(SIGPIPE, SIG_IGN) == SIG_ERR) {
        perror("signal");
        return 1;
    }
    /* Later, every send() then fails with EPIPE instead of killing you: */
    int fd = -1;   /* stand-in for a client socket */
    if (send(fd, "x", 1, 0) < 0) {
        if (errno == EPIPE)
            fprintf(stderr, "client went away\n");
        else
            perror("send");
    }
    return 0;
}
```

Per-call alternatives:
1. Linux: `send(fd, buf, n, MSG_NOSIGNAL)`.
2. macOS/BSD: `setsockopt(fd, SOL_SOCKET, SO_NOSIGPIPE, &on, sizeof on)` once per socket.

Key points:
- `ECONNRESET` is another normal "client vanished" error; close the socket and move on.
- Exit codes above 128 almost always mean "killed by signal (code - 128)".

`poll()` waits until any of several file descriptors is ready. One process can then serve many clients: the listening socket becomes readable when a client connects, and each client socket becomes readable when data arrives.

```c
#define _POSIX_C_SOURCE 200809L
#include <netinet/in.h>
#include <poll.h>
#include <stdio.h>
#include <string.h>
#include <sys/socket.h>
#include <unistd.h>

#define MAXFD 64

int main(void)
{
    int srv = socket(AF_INET, SOCK_STREAM, 0);
    if (srv < 0) { perror("socket"); return 1; }
    int on = 1;
    setsockopt(srv, SOL_SOCKET, SO_REUSEADDR, &on, sizeof on);
    struct sockaddr_in a;
    memset(&a, 0, sizeof a);
    a.sin_family = AF_INET;
    a.sin_port = htons(5000);
    a.sin_addr.s_addr = htonl(INADDR_ANY);
    if (bind(srv, (struct sockaddr *)&a, sizeof a) < 0 || listen(srv, 16) < 0) {
        perror("bind/listen"); return 1;
    }
    struct pollfd fds[MAXFD];
    nfds_t n = 1;
    fds[0].fd = srv;
    fds[0].events = POLLIN;

    for (;;) {
        if (poll(fds, n, -1) < 0) { perror("poll"); return 1; }
        if ((fds[0].revents & POLLIN) && n < MAXFD) {
            int c = accept(srv, NULL, NULL);
            if (c >= 0) { fds[n].fd = c; fds[n].events = POLLIN; fds[n].revents = 0; n++; }
        }
        for (nfds_t i = 1; i < n; i++) {
            if (!(fds[i].revents & (POLLIN | POLLHUP | POLLERR))) continue;
            char buf[4096];
            ssize_t r = recv(fds[i].fd, buf, sizeof buf, 0);
            if (r <= 0 || send(fds[i].fd, buf, (size_t)r, 0) < 0) {
                close(fds[i].fd);
                fds[i] = fds[n - 1];     /* move last entry into this slot */
                n--;
                i--;                     /* recheck the moved entry */
            }
        }
    }
}
```

Test: open several terminals and run `nc 127.0.0.1 5000` in each.

Key points:
- `revents` is filled in by `poll()`; `events` is what you asked to watch.
- For simplicity this server assumes `send()` writes everything at once and does not handle `SIGPIPE`; production code needs both (non-blocking sockets plus a per-client output buffer).
- Linux `epoll` and BSD/macOS `kqueue` scale better for thousands of clients, but are not portable.

